#include <iostream>
using namespace std;

int main() {
    int panjang, lebar;
    cin >> panjang >> lebar;
    cout << panjang * lebar << endl;
    cout << 2 * (panjang + lebar) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int panjang, lebar;
    cin >> panjang >> lebar;
    if (panjang > lebar) {
        cout << panjang << endl;
    } else {
        cout << lebar << endl;
    }
    return 0;
}
